@import "@fontsource-variable/geist";
@import "@fontsource-variable/jetbrains-mono";
@import "@fontsource-variable/saira/wdth-italic.css";

/* Light (faithful): white page, black ink, #666 secondary text (ink at 60%), #f0f0f0 panels,
   cobalt #112baf for buy buttons, a battery green (#2fb52a / #44d63e) for highlights and glows. */
:root {
  --background: #ffffff;
  --foreground: #000000;
  --card: #ffffff;
  --card-foreground: #000000;
  --popover: #ffffff;
  --popover-foreground: #000000;
  --primary: #112baf;
  --primary-foreground: #ffffff;
  --secondary: #f0f0f0;
  --secondary-foreground: #000000;
  --muted: #f0f0f0;
  --muted-foreground: #666666;
  --accent: #f5f5f5;
  --accent-foreground: #000000;
  --destructive: #d0302b;
  --destructive-foreground: #ffffff;
  --border: #e5e5e5;
  --input: #d6d6d6;
  --ring: #112baf;
  --highlight: #2fb52a;
  --highlight-foreground: #ffffff;
  --glow: #44d63e;
  --chart-1: #112baf;
  --chart-2: #2fb52a;
  --chart-3: #c4beb1;
  --chart-4: #6b7cd6;
  --chart-5: #e59a3b;
  --sidebar: #f0f0f0;
  --sidebar-foreground: #000000;
  --sidebar-primary: #112baf;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #e5e5e5;
  --sidebar-accent-foreground: #000000;
  --sidebar-border: #e5e5e5;
  --sidebar-ring: #112baf;

  --typeface-body: "Geist Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Geist Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "JetBrains Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  /* promo headlines: ultrahuman blocks read var(--ultrahuman-condensed, var(--typeface-display))
     and ask for font-stretch 50% (Saira's Extra Condensed end) */
  --ultrahuman-condensed: "Saira Variable", "Arial Narrow", sans-serif;
  /* Saira's narrowest cut still sets ~15% wider than the original's gothic: promo headlines
     subtract this from their tracking (unset, so 0, under other themes) */
  --ultrahuman-squeeze: 0.03em;
  --radius: 1rem;
  --page-width: 80rem;
  --page-gutter: 1.25rem;
  --section-y: 7.5rem;
}

/* Dark sibling, and the colours of the original's black product band: #000 page, #1a1a1a
   cards, white at 10% for active pills, white at 60% for secondary text; blue stays blue. */
.dark {
  --background: #000000;
  --foreground: #ffffff;
  --card: #1a1a1a;
  --card-foreground: #ffffff;
  --popover: #1a1a1a;
  --popover-foreground: #ffffff;
  --primary: #1733c9;
  --primary-foreground: #ffffff;
  --secondary: #1a1a1a;
  --secondary-foreground: #ffffff;
  --muted: #1a1a1a;
  --muted-foreground: #999999;
  --accent: #262626;
  --accent-foreground: #ffffff;
  --destructive: #ef5350;
  --destructive-foreground: #ffffff;
  --border: rgb(255 255 255 / 12%);
  --input: rgb(255 255 255 / 16%);
  --ring: #6b7cf0;
  --highlight: #44d63e;
  --highlight-foreground: #000000;
  --glow: #44d63e;
  --chart-1: #6b7cf0;
  --chart-2: #44d63e;
  --chart-3: #c4beb1;
  --chart-4: #8f9cf5;
  --chart-5: #f0b24f;
  --sidebar: #1a1a1a;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #1733c9;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #262626;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: rgb(255 255 255 / 12%);
  --sidebar-ring: #6b7cf0;
}
